# Install only a Conductor skill, SSH command wrapper and VM alias for this user.
param(
    [string]$VmHost,
    [string]$TestRoot,
    [switch]$PayloadCheck
)
$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
# The payload below is generated from client/ and skills/ by scripts/build_windows_installer.py.
# BEGIN EMBEDDED CONDUCTOR FILES
$embeddedFiles = @{
    'client/conductor.ps1' = ''
    'skills/conductor-coordinator/SKILL.md' = ''
    'skills/conductor-coordinator/references/workflow.md' = ''
    'skills/conductor-coordinator/references/actions.md' = ''
}
# END EMBEDDED CONDUCTOR FILES
function Get-EmbeddedText([string]$name) {
    if (-not $embeddedFiles.ContainsKey($name)) { throw "Installer payload is missing $name." }
    return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($embeddedFiles[$name]))
}
$clientSourceText = Get-EmbeddedText 'client/conductor.ps1'
$skillText = Get-EmbeddedText 'skills/conductor-coordinator/SKILL.md'
$workflowText = Get-EmbeddedText 'skills/conductor-coordinator/references/workflow.md'
$actionsText = Get-EmbeddedText 'skills/conductor-coordinator/references/actions.md'
if ($PayloadCheck) {
    Write-Host 'Standalone Conductor installer payload is complete.'
    return
}
if (-not $VmHost) { $VmHost = Read-Host 'Conductor VM SSH alias, hostname, or IP' }
if ($VmHost -notmatch '^(?:[A-Za-z_][A-Za-z0-9_.-]*@)?[A-Za-z0-9_][A-Za-z0-9_.-]{0,252}$') {
    throw 'Enter an SSH alias, hostname, IP address, or login@host. Jump hosts remain in your usual SSH settings.'
}
if (-not (Get-Command ssh.exe -ErrorAction SilentlyContinue)) {
    throw 'Windows OpenSSH Client is required.'
}
Write-Host 'Checking your existing SSH login. SSH may ask for its normal host trust or sign-in.'
$candidates = @($VmHost)
if ($VmHost -notmatch '@') { $candidates += @("$env:USERNAME@$VmHost", "ubuntu@$VmHost") }
$target = $null
foreach ($candidate in ($candidates | Select-Object -Unique)) {
    try {
        & ssh.exe -T -o ConnectTimeout=10 $candidate 'true' 2>$null
        if ($LASTEXITCODE -eq 0) { $target = $candidate; break }
    } catch {
        # Windows PowerShell 5.1 turns a rejected candidate's stderr into an exception.
    }
}
if (-not $target) {
    if ($VmHost -match '@') { throw 'That SSH login could not connect. Check its key, agent or jump-host settings.' }
    $login = Read-Host 'SSH login on this VM (Linux username)'
    if ($login -notmatch '^[A-Za-z_][A-Za-z0-9_.-]*$') { throw 'Invalid SSH login.' }
    $target = "$login@$VmHost"
    & ssh.exe -T -o ConnectTimeout=10 $target 'true'
    if ($LASTEXITCODE -ne 0) { throw 'SSH login failed. Check your existing SSH key, agent or jump-host settings.' }
}
& ([scriptblock]::Create($clientSourceText)) -Action coordination_health -HostAlias $target | Out-Null

$codexRoot = if ($TestRoot) { Join-Path $TestRoot '.codex' } else { Join-Path $HOME '.codex' }
$client = Join-Path $codexRoot 'conductor-client'
$legacySkill = if ($TestRoot) { Join-Path $TestRoot '.agents\skills\conductor-coordinator' } else { Join-Path $HOME '.agents\skills\conductor-coordinator' }
$skill = if (Test-Path -LiteralPath $legacySkill) { $legacySkill } else { Join-Path $codexRoot 'skills\conductor-coordinator' }
$marker = Join-Path $client '.conductor-ssh-client.json'
if ((Test-Path -LiteralPath $client) -and -not (Test-Path -LiteralPath $marker -PathType Leaf)) {
    throw "An unrelated client directory already exists at $client; it was preserved."
}
$skillMarker = Join-Path $skill '.conductor-ssh-skill'
$migrateSkill = (Test-Path -LiteralPath $skill) -and -not (Test-Path -LiteralPath $skillMarker -PathType Leaf)
if ($migrateSkill) {
    $skillFile = Join-Path $skill 'SKILL.md'
    $workflowFile = Join-Path $skill 'references\workflow.md'
    if (-not (Test-Path -LiteralPath $skillFile -PathType Leaf) -or -not (Test-Path -LiteralPath $workflowFile -PathType Leaf)) {
        throw "An existing Conductor skill is at $skill; it was preserved."
    }
    $hash = [System.Security.Cryptography.SHA256]::Create()
    $skillText = (Get-Content -LiteralPath $skillFile -Raw -Encoding UTF8).Replace("`r`n", "`n")
    $workflowText = (Get-Content -LiteralPath $workflowFile -Raw -Encoding UTF8).Replace("`r`n", "`n")
    $skillHash = [BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($skillText))).Replace('-', '').ToLower()
    $workflowHash = [BitConverter]::ToString($hash.ComputeHash([Text.Encoding]::UTF8.GetBytes($workflowText))).Replace('-', '').ToLower()
    if ($skillHash -ne '80965f7144c686bb627ed761357a3c58c4ee4b468a0c74c747f1fc8a5abaac21' -or
        $workflowHash -ne '9aedffbae77075e0511b6f820be32bb1a79b483e8f176a61d2ff132db9202677') {
        throw "The existing Conductor skill has changes this installer cannot safely replace: $skill"
    }
}
$config = Join-Path $codexRoot 'config.toml'
$legacyBlock = $null
if (Test-Path -LiteralPath $config -PathType Leaf) {
    $original = [System.IO.File]::ReadAllText($config)
    $legacyBlock = [regex]::Match($original, '(?ms)^\[mcp_servers\.conductor_coordination\]\r?\n.*?(?=^\[|\z)')
    if ($legacyBlock.Success -and ($legacyBlock.Value -notmatch 'conductor_coordination\.client_bridge' -or
        $legacyBlock.Value -notmatch 'conductor-coordination.*client\.json')) {
        throw 'An unfamiliar Conductor MCP entry exists in Codex config; it was preserved.'
    }
}
New-Item -ItemType Directory -Path $client -Force | Out-Null
if ($migrateSkill) {
    $backup = Join-Path $client 'legacy-skill-backup'
    if (Test-Path -LiteralPath $backup) { throw "Existing skill backup was preserved: $backup" }
    Copy-Item -LiteralPath $skill -Destination $backup -Recurse
}
if ($legacyBlock -and $legacyBlock.Success) {
    $backup = Join-Path $client 'config-before-ssh.toml'
    if (Test-Path -LiteralPath $backup) {
        throw 'Existing Conductor config backup was preserved; review it before retrying.'
    }
    Copy-Item -LiteralPath $config -Destination $backup
    $sid = ((& whoami /user /fo csv /nh) -split ',')[1].Trim('"')
    & icacls $backup /inheritance:r /grant:r "*${sid}:(F)" | Out-Null
    if ($LASTEXITCODE -ne 0) { throw 'Could not protect the Conductor configuration backup.' }
    $updated = $original.Remove($legacyBlock.Index, $legacyBlock.Length)
    try {
        [System.IO.File]::WriteAllText($config, $updated, (New-Object System.Text.UTF8Encoding($false)))
    } catch {
        Copy-Item -LiteralPath $backup -Destination $config -Force
        throw
    }
}
New-Item -ItemType Directory -Path $skill -Force | Out-Null
[IO.File]::WriteAllText((Join-Path $client 'conductor.ps1'), $clientSourceText, [Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $skill 'SKILL.md'), $skillText, [Text.UTF8Encoding]::new($false))
New-Item -ItemType Directory -Path (Join-Path $skill 'references') -Force | Out-Null
[IO.File]::WriteAllText((Join-Path $skill 'references\workflow.md'), $workflowText, [Text.UTF8Encoding]::new($false))
[IO.File]::WriteAllText((Join-Path $skill 'references\actions.md'), $actionsText, [Text.UTF8Encoding]::new($false))
Set-Content -LiteralPath (Join-Path $client 'host.txt') -Value $target -NoNewline
Set-Content -LiteralPath $marker -Value '{"owner":"conductor-ssh-client"}' -NoNewline
Set-Content -LiteralPath (Join-Path $skill '.conductor-ssh-skill') -Value 'conductor-ssh-client' -NoNewline
Write-Host 'Conductor SSH client is ready for Codex desktop and VS Code. Open a new chat to load the skill.'
